","newText":"from __future__ import annotations

import json
import logging
from collections.abc import Mapping
from typing import Any

from flask import Request, Response

_SENSITIVE_HEADERS = {
    "authorization",
    "cookie",
    "proxy-authorization",
    "set-cookie",
    "x-api-key",
    "x-auth-token",
}


def _redact_headers(headers: Mapping[str, str]) -> dict[str, str]:
    """Return headers safe for audit logs, with credentials removed."""
    return {
        name: ("[REDACTED]" if name.lower() in _SENSITIVE_HEADERS else value)
        for name, value in headers.items()
    }


def audit_log(logger: logging.Logger, request: Request, response: Response) -> None:
    """Write a per-request audit entry for this request/response.

    The profile API returns account-holder personal data and receives bearer
    credentials from the gateway.  To keep the audit trail useful without
    duplicating secrets or PII into log files, record request/response metadata,
    byte counts, and redacted headers rather than raw bodies.
    """
    entry: dict[str, Any] = {
        "event": "http_request",
        "request": {
            "method": request.method,
            "path": request.path,
            "headers": _redact_headers(request.headers),
            "body_bytes": len(request.get_data(cache=True) or b""),
            "remote_addr": request.remote_addr,
        },
        "response": {
            "status": response.status_code,
            "headers": _redact_headers(response.headers),
            "body_bytes": response.calculate_content_length() or 0,
        },
    }
    logger.info(json.dumps(entry, sort_keys=True, separators=(",", ":")))
